contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: target address and value to send to multiplicate
    function run(address adr, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract has enough ETH to send
        require(address(this).balance >= amount);

        // observe Owner before the call and c's balance before
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        bool reverted;
        c.multiplicate{value: amount}(adr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-state
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // Assert general rule: if the call succeeded and the contract's balance became zero
        // (i.e., multiplicate effectuated an outgoing transfer of the entire funds it had plus sent value),
        // then Owner must be unchanged.
        assert((!reverted && balAfter == 0 && ownerAfter == ownerBefore) || reverted || (balAfter != 0));
    }

    receive() external payable {}
}

